SELECT wr_reason_sk, i_category, total_loss, return_cnt, loss_category, MAX(total_loss) OVER (PARTITION BY i_category) AS max_category_loss, total_loss / MAX(total_loss) OVER (PARTITION BY i_category) * 100 AS loss_pct FROM ( SELECT wr.wr_reason_sk, i.i_category, SUM(wr.wr_net_loss) AS total_loss, COUNT(*) AS return_cnt, CASE WHEN SUM(wr.wr_net_loss) > 22000 THEN 'HIGH' WHEN SUM(wr.wr_net_loss) > 11000 THEN 'MEDIUM' ELSE 'LOW' END AS loss_category FROM web_returns wr JOIN item i ON wr.wr_item_sk = i.i_item_sk JOIN customer_address ca ON wr.wr_returning_addr_sk = ca.ca_address_sk WHERE wr.wr_return_quantity > 1 GROUP BY wr.wr_reason_sk, i.i_category ) agg ORDER BY loss_pct DESC
